namespace Deception.Tests{public static class TransformationTests{
 static double Now;
 static List<string> Cases=new();static int Assertions;static void Check(bool b,string why){Assertions++;if(!b)throw new Exception(why);}static void Test(string n,Action a){try{a();Cases.Add(n);}catch(Exception e){throw new Exception(n,e);}}
 sealed record Rig(GameState State,MapRenderer Map,Unit A,Unit B,NativeExchangeIntent Intent,NativeIdentityLedger Ledger){public Unit Recipient=>Intent.Kind==NativeExchangeKind.Regroup?A:B;}
 static LedgerAppearance App(string form)=>new(form,new("Imperius","Default"),new("Imperius","Default"),new("Imperius","Default"),2,100,100,false,ApparentConcealment.Visible,-1,Array.Empty<string>());
 static Rig Setup(NativeExchangeKind kind=NativeExchangeKind.Regroup,bool swap=false,bool coast=false,string form="giant"){
  NativeExchangeTransformationVisual.ClearDisappearances();Now=100;NativeExchangeTransformationVisual.Clock=()=>Now;
  NativeGameStateEnvelope.Bindings.Clear();NativeVisualSnapshot.Calls.Clear();NativeVisualSnapshot.Fail=false;UnityEngine.GameObject.All.Clear();UnityEngine.GameObject.FailAdd=false;GameManager.Viewing=true;HotSeatOverlay.IsActive=false;
  GameManager.Client=new();GameManager.LocalPlayer=new();var state=new GameState();GameManager.GameState=state;GameManager.Client.GameState=state;var map=new MapRenderer();MapRenderer.Current=map;
  var a=new Unit{UnitState=new(){id=11,coordinates=new(swap?2:1,1)}};var b=new Unit{UnitState=new(){id=12,coordinates=new(swap?1:2,1),health=400,type="giant"}};
  var tileA=new Tile{Data=new(){coordinates=new(1,1),unit=swap?b.UnitState:a.UnitState},unit=a};var tileB=new Tile{Data=new(){coordinates=new(2,1),unit=swap?a.UnitState:b.UnitState},unit=b};
  state.Map.Tiles.AddRange(new[]{tileA.Data,tileB.Data});map.Tiles.AddRange(new[]{tileA,tileB});map.Units[11]=a;map.Units[12]=b;
  var epoch=Guid.NewGuid();var intent=new NativeExchangeIntent(epoch,1,0,3,1,kind,swap,NativePartnerReference.Existing,3,new(1,11,1,1),new(2,12,2,1),new byte[32]);
  var recipient=kind==NativeExchangeKind.Regroup?a:b;uint rid=recipient.UnitState.id;ulong logical=kind==NativeExchangeKind.Regroup?1ul:2ul;
  if(coast){var wrapper=new UnitState{id=37,health=10,coordinates=recipient.UnitState.coordinates,passengerUnit=recipient.UnitState};state.Map.Tiles.Single(t=>ReferenceEquals(t.unit,recipient.UnitState)).unit=wrapper;rid=37;}
  var rows=new[]{new LedgerUnit(1,logical==1?rid:11,true,LedgerActualKind.Mimic,true,logical==1?App(form):App("warrior"),PaidInvestmentKind.Known,3),new LedgerUnit(2,logical==2?rid:12,true,LedgerActualKind.Genuine,logical==2,logical==2?App(form):null,PaidInvestmentKind.Known,20)};
  var receipt=new LedgerReceipt(1,NativeExchangeIntentCodec.Operation(1),NativeExchangeIntentCodec.Fingerprint(intent),0,1,new ulong[]{1,2});var ledger=new NativeIdentityLedger(epoch,3,2,rows,new[]{receipt});
  Bind(state,ledger);return new(state,map,a,b,intent,ledger);
 }
 static void Bind(GameState state,NativeIdentityLedger ledger)=>NativeGameStateEnvelope.Bindings[state]=new NativeGameStateEnvelope.Snapshot(1,NativeIdentityLedgerCodec.Encode(ledger,1));
 static NativeExchangeTransformationVisual.Lease? Begin(Rig r)=>NativeExchangeTransformationVisual.Begin(r.State,r.Map,GameManager.Client,GameManager.LocalPlayer,r.Intent);
 sealed record Transition(Action? Complete,Action Commit,NativeGameStateEnvelope.Snapshot Before);
 static Transition Observe(Rig r,Action? pre=null){
  GameManager.LocalPlayer.Id=2;
  var afterUnits=r.Map.Tiles.Select(t=>t.Data.unit!).ToArray();var afterCoordinates=afterUnits.Select(u=>u.coordinates).ToArray();
  r.Map.Tiles[0].Data.unit=r.A.UnitState;r.Map.Tiles[1].Data.unit=r.B.UnitState;r.A.UnitState.coordinates=new(1,1);r.B.UnitState.coordinates=new(2,1);
  var beforeRows=r.Ledger.Units.Select(row=>row with{NativeId=row.LogicalId==1?11u:12u,Appearance=row.LogicalId==1?App("warrior"):null,Independent=row.LogicalId==1}).ToArray();
  var beforeLedger=r.Ledger with{Units=beforeRows,Receipts=Array.Empty<LedgerReceipt>(),NextSequence=1};
  var before=new NativeGameStateEnvelope.Snapshot(0,NativeIdentityLedgerCodec.Encode(beforeLedger,0));NativeGameStateEnvelope.Bindings[r.State]=before;
  pre?.Invoke();var complete=NativeExchangeTransformationVisual.PrepareDisappearance(r.State,r.Intent);
  return new(complete,()=>{
   for(int i=0;i<afterUnits.Length;i++){r.Map.Tiles[i].Data.unit=afterUnits[i];afterUnits[i].coordinates=afterCoordinates[i];}
   ulong id=r.Intent.Kind==NativeExchangeKind.Regroup?1ul:2ul;
   Bind(r.State,r.Ledger with{Units=r.Ledger.Units.Select(row=>row.LogicalId==id?row with{Appearance=App("cloak") with{Concealment=ApparentConcealment.Hidden}}:row).ToArray()});
   var recipient=r.Map.Tiles.Single(t=>t.Data.unit!.id==(r.Ledger.Units.Single(row=>row.LogicalId==id).NativeId));recipient.Data.Visible=false;
   r.Recipient.Invisible=true;
  },before);
 }
 static NativeExchangeTransformationVisual.Disappearance? CommitAndTake(Rig r,Transition t){t.Commit();t.Complete?.Invoke();return NativeExchangeTransformationVisual.TakeDisappearance(r.State,r.Intent);}
 static void Unchanged(Rig r){Check(r.A.UnitState.health==10&&r.B.UnitState.health==400&&!r.A.UnitState.moved&&!r.A.UnitState.attacked&&r.A.UnitState.effects.Count==0&&r.A.UnitState.type=="dcp_mimic_form_warrior"&&r.B.UnitState.type=="giant"&&r.A.UnitState.owner==1&&r.B.UnitState.owner==1,"no real fields changed");}
 public static int Run(){try{
  foreach(var kind in new[]{NativeExchangeKind.Regroup,NativeExchangeKind.Disguise})foreach(bool swap in new[]{false,true})Test($"recipient-art-before-placement-{kind}-{swap}",()=>{
   var r=Setup(kind,swap);var nativeContainer=r.Recipient.spriteContainer;var donor=kind==NativeExchangeKind.Regroup?r.B:r.A;using(var lease=Begin(r)){
    Check(lease!=null&&NativeExchangeTransformationVisual.Current(lease),"exact committed recipient can display");Check(ReferenceEquals(lease!.Unit,r.Recipient)&&ReferenceEquals(((UnityEngine.GameObject)lease.Root).transform.parent,r.Recipient.transform),"overlay parent is old recipient, never donor after Swap");
    Check(!nativeContainer.gameObject.activeSelf&&donor.spriteContainer.gameObject.activeSelf,"only recipient original body is temporarily hidden");
    Check(NativeVisualSnapshot.Calls.Single().Form=="giant"&&((UnityEngine.GameObject)lease.Root).transform.Children.Select(t=>((UnityEngine.SpriteRenderer)t.gameObject.Part!).sprite!.Name).All(n=>n.StartsWith("giant")),"copy uses postcommit recipient appearance");
    Check(NativeGameStateEnvelope.Get(r.State)!.Bytes().SequenceEqual(NativeIdentityLedgerCodec.Encode(r.Ledger,1)),"private payload unchanged");Unchanged(r);
   }Check(nativeContainer.gameObject.activeSelf&&UnityEngine.GameObject.All.Where(g=>g.name.StartsWith("Deception")).All(g=>g.Destroyed),"restored native body and all transient children destroyed");
  });
  foreach(bool swap in new[]{false,true})Test("coast-rebind-keeps-original-recipient-"+swap,()=>{var r=Setup(swap:swap,coast:true,form:"juggernaut");using var l=Begin(r);Check(l!=null&&l.Row.NativeId==37&&ReferenceEquals(l.Unit,r.A),"new backend wrapper row follows logical ID; old visible recipient remains original body");Unchanged(r);});
  Test("deep-copied-passenger-remains-valid",()=>{var r=Setup(form:"juggernaut");var row=r.Ledger.Units[0] with{Appearance=App("juggernaut") with{Passenger=App("warrior") with{Effects=new[]{"Swift"}}}};Bind(r.State,r.Ledger with{Units=new[]{row,r.Ledger.Units[1]}});using var l=Begin(r);Check(l!=null&&NativeExchangeTransformationVisual.Current(l)&&NativeExchangeTransformationVisual.Current(l),"production Snapshot copies nested arrays on every read");});
  foreach(string form in new[]{RecruitmentCatalog.MenuId,SpyCatalog.Id,AquarionCatalog.MimicId,SpyCatalog.AquarionId,FoggerCatalog.Id,"customBoat"})Test("custom-public-art-"+form,()=>{var r=Setup(form:form=="customBoat"?"transportship":form);if(form=="customBoat")Bind(r.State,r.Ledger with{Units=new[]{r.Ledger.Units[0] with{Appearance=App("transportship") with{Passenger=App(RecruitmentCatalog.MenuId)}},r.Ledger.Units[1]}});using var l=Begin(r);Check(l!=null,"custom form drawn");var names=((UnityEngine.GameObject)l!.Root).transform.Children.Select(t=>((UnityEngine.SpriteRenderer)t.gameObject.Part!).sprite!.Name);Check(names.Contains(form==FoggerCatalog.Id?"Fogger":form==SpyCatalog.AquarionId?"Spymaid":form==AquarionCatalog.MimicId?"Mermimic":form==SpyCatalog.Id?"Spy":form=="customBoat"?"MimicBoat":"Mimic"),"custom artwork, never warrior fallback");});
  Test("multipart-native-carrier-has-no-root-sprite",()=>{var r=Setup();r.A.SpriteRenderer=null!;r.A.skinVisuals.visualParts.Add(new(){renderer=new(){spriteRenderer=new UnityEngine.SpriteRenderer{sortingOrder=8,sortingLayerID=4}}});using var l=Begin(r);Check(l!=null&&((UnityEngine.GameObject)l.Root).transform.Children.All(t=>((UnityEngine.SpriteRenderer)t.gameObject.Part!).sortingLayerID==4),"native multipart carriers use their actual skin main renderer");});
  Test("enrolled-recap-observer-accepted",()=>{var r=Setup(swap:true);GameManager.Client.IsRecap=true;GameManager.LocalPlayer.Id=2;using var l=Begin(r);Check(l!=null,"recap is observed current enrolled state");Unchanged(r);});
  foreach(string blocked in new[]{"none","invisible","hidden","missing","blackout"})Test("endpoint-puff-access-"+blocked,()=>{var r=Setup();switch(blocked){case "invisible":r.A.Invisible=true;break;case "hidden":r.A.Visible=false;break;case "missing":r.Map.Tiles[0].Data.Visible=false;break;case "blackout":r.Map.Tiles[0].Data.Explored=false;break;}Check(NativeExchangeTransformationVisual.CanShowEndpoint(r.State,r.Map,2,new WorldCoordinates(1,1))==(blocked=="none"),"a tile alone cannot disclose hidden occupant via poof");});
  foreach(string guard in new[]{"unready","replay","spectator","overlay","notviewing","uncommitted","wrongfingerprint","wrongactor","oldendpointfog","destinationfog","blackout","invisible","actualview","pool","binding","dead","wrongroot","unexplored","hiddenunit","renderhidden","inactivemap","clientstate"})Test("initial-guard-"+guard,()=>{
   var r=Setup(swap:true);switch(guard){case "unready":r.State.Admitted=false;break;case "replay":GameManager.Client.IsReplay=true;break;case "spectator":GameManager.Client.IsSpectating=true;break;case "overlay":HotSeatOverlay.IsActive=true;break;case "notviewing":GameManager.Viewing=false;break;
    case "uncommitted":Bind(r.State,r.Ledger with{Receipts=Array.Empty<LedgerReceipt>(),NextSequence=1});break;case "wrongfingerprint":r=r with{Intent=r.Intent with{SourceAppearanceHash=Enumerable.Repeat((byte)1,32).ToArray()}};break;case "wrongactor":r.A.UnitState.owner=2;break;
    case "oldendpointfog":r.Map.Tiles[0].IsHidden=true;break;case "destinationfog":r.Map.Tiles[1].IsHidden=true;break;case "blackout":r.Map.Tiles[1].Data.Explored=false;break;case "invisible":r.A.Invisible=true;break;case "actualview":r.A.Actual=true;break;
    case "pool":r.Map.Units[11]=new Unit{UnitState=r.A.UnitState};break;case "binding":r.A.UnitState=new(){id=99};break;case "dead":r.A.UnitState.health=0;break;case "wrongroot":r.Map.Tiles[1].Data.unit=new(){id=99};break;case "unexplored":r.Map.Tiles[0].Data.Explored=false;break;case "hiddenunit":r.Map.Tiles[1].Data.Visible=false;break;case "renderhidden":r.A.Visible=false;break;case "inactivemap":r.Map.gameObject.SetActive(false);break;case "clientstate":GameManager.Client.GameState=new();break;
   }NativeExchangeTransformationVisual.Lease? l=null;try{l=Begin(r);}catch(System.IO.InvalidDataException){}Check(l==null&&r.A.spriteContainer.gameObject.activeSelf&&NativeVisualSnapshot.Calls.Count==0,"guard emits no borrowed art and does not hide native body");
  });
  foreach(string changed in new[]{"state","map","client","player","epoch","profile","cargo","fog","actualview","pool","container","body","samebodyid","parent","clientstate","mapdestroyed"})Test("lease-revalidates-"+changed,()=>{
   var r=Setup(form:"juggernaut");var l=Begin(r)!;var old=r.A.spriteContainer.gameObject;switch(changed){case "state":GameManager.GameState=new();break;case "clientstate":GameManager.Client.GameState=new();break;case "map":MapRenderer.Current=new();break;case "mapdestroyed":r.Map.Destroyed=true;break;case "client":GameManager.Client=new();break;case "player":GameManager.LocalPlayer=new();break;case "epoch":Bind(r.State,r.Ledger with{Epoch=Guid.NewGuid()});break;case "profile":Bind(r.State,r.Ledger with{Units=new[]{r.Ledger.Units[0] with{Appearance=App("knight")},r.Ledger.Units[1]}});break;case "cargo":Bind(r.State,r.Ledger with{Units=new[]{r.Ledger.Units[0] with{Appearance=App("juggernaut") with{Passenger=App("warrior")}},r.Ledger.Units[1]}});break;case "fog":r.Map.Tiles[0].IsHidden=true;break;case "actualview":r.A.Actual=true;break;case "pool":r.Map.Units[11]=new Unit{UnitState=r.A.UnitState};break;case "container":r.A.spriteContainer=new UnityEngine.GameObject("new owner").transform;break;case "body":r.A.UnitState=new(){id=11};break;case "samebodyid":r.A.UnitState.id=44;break;case "parent":r.A.spriteContainer.SetParent(new UnityEngine.GameObject().transform,false);break;}
   Check(!NativeExchangeTransformationVisual.Current(l),"stale visual loses authority");var root=(UnityEngine.GameObject)l.Root;l.Dispose();l.Dispose();Check(root.Destroyed&&!root.activeSelf,"lease disposal idempotent");Check(old.activeSelf==(changed is not "pool" and not "container" and not "body" and not "samebodyid" and not "parent" and not "mapdestroyed"),"do not reactivate a recycled container");
  });
  foreach(bool allocation in new[]{false,true})Test("allocation-failure-preserves-native-"+allocation,()=>{var r=Setup();NativeVisualSnapshot.Fail=!allocation;UnityEngine.GameObject.FailAdd=allocation;bool failed=false;try{Begin(r);}catch{failed=true;}Check(failed&&r.A.spriteContainer.gameObject.activeSelf&&UnityEngine.GameObject.All.Where(g=>g.name.StartsWith("Deception")).All(g=>g.Destroyed),"partial visual destroyed before any native art is hidden");Unchanged(r);});
  foreach(var kind in new[]{NativeExchangeKind.Regroup,NativeExchangeKind.Disguise})foreach(bool swap in new[]{false,true})Test($"witnessed-hidden-departure-{kind}-{swap}",()=>{
   var r=Setup(kind,swap);var t=Observe(r);Check(t.Complete!=null,"exact originally visible recipient captured before mutation");var p=CommitAndTake(r,t);var at=kind==NativeExchangeKind.Regroup?r.Intent.Initiator:r.Intent.Partner;
   Check(p!=null&&NativeExchangeTransformationVisual.CanShowDisappearance(p,at.X,at.Y),"hidden recipient permits original observed tile puff");Check(!NativeExchangeTransformationVisual.CanShowDisappearance(p,at.X==1?2:1,at.Y),"hidden donor or destination never gains location cue");
   Check(Begin(r)==null&&NativeVisualSnapshot.Calls.Count==0,"never paint the copied hidden form");Check(NativeExchangeTransformationVisual.TakeDisappearance(r.State,r.Intent)==null,"receipt cue claimed once");Unchanged(r);
  });
  Test("hidden-departure-new-native-wrapper",()=>{var r=Setup(swap:true,coast:true);var p=CommitAndTake(r,Observe(r));Check(p!=null&&p.Row.NativeId==37&&NativeExchangeTransformationVisual.CanShowDisappearance(p,1,1),"logical recipient survives authorized native root rebind; only old visible endpoint emits");});
  Test("hidden-departure-enrolled-opponent-recap",()=>{var r=Setup();GameManager.Client.IsRecap=true;var p=CommitAndTake(r,Observe(r));Check(p!=null,"enrolled active observer recap uses same precommit proof");});
  foreach(string guard in new[]{"prehidden","prerenderhidden","prefog","preunexplored","prerenderbinding","replay","spectator","overlay","notviewing","wrongturn","clientstate","wrongbefore"})Test("hidden-departure-capture-denied-"+guard,()=>{
   var r=Setup();var t=Observe(r,()=>{switch(guard){case "prehidden":r.Map.Tiles[0].Data.Visible=false;break;case "prerenderhidden":r.A.Invisible=true;break;case "prefog":r.Map.Tiles[0].IsHidden=true;break;case "preunexplored":r.Map.Tiles[0].Data.Explored=false;break;case "prerenderbinding":r.A.UnitState=new(){id=11};break;case "replay":GameManager.Client.IsReplay=true;break;case "spectator":GameManager.Client.IsSpectating=true;break;case "overlay":HotSeatOverlay.IsActive=true;break;case "notviewing":GameManager.Viewing=false;break;case "wrongturn":r.State.CurrentTurn++;break;case "clientstate":GameManager.Client.GameState=new();break;case "wrongbefore":NativeGameStateEnvelope.Bindings[r.State]=new(1,NativeIdentityLedgerCodec.Encode(r.Ledger,1));break;}});
   Check(t.Complete==null,"postcommit hidden status cannot create missing prior observer proof");t.Commit();Check(NativeExchangeTransformationVisual.TakeDisappearance(r.State,r.Intent)==null,"denied capture never leaves queued cue");
  });
  Test("hidden-departure-failed-commit-does-not-queue",()=>{var r=Setup();var t=Observe(r);t.Complete?.Invoke();Check(NativeExchangeTransformationVisual.PendingDisappearances==0,"unchanged old revision is not a successful exchange");});
  Test("hidden-departure-uncommitted-receipt-does-not-queue",()=>{var r=Setup();var t=Observe(r);t.Commit();var frame=NativeGameStateEnvelope.Get(r.State)!;var ledger=NativeIdentityLedgerCodec.Decode(frame.Bytes(),frame.Revision);Bind(r.State,ledger with{Receipts=Array.Empty<LedgerReceipt>(),NextSequence=1});t.Complete?.Invoke();Check(NativeExchangeTransformationVisual.PendingDisappearances==0,"requires exact authoritative completed receipt");});
  Test("hidden-departure-visible-result-keeps-native-cue-path",()=>{var r=Setup();var t=Observe(r);t.Commit();Bind(r.State,r.Ledger);t.Complete?.Invoke();Check(NativeExchangeTransformationVisual.PendingDisappearances==0,"visible-copy exchange does not gain departure exception");});
  Test("hidden-departure-duplicate-completion",()=>{var r=Setup();var t=Observe(r);t.Commit();t.Complete?.Invoke();t.Complete?.Invoke();Check(NativeExchangeTransformationVisual.PendingDisappearances==1,"accepted callback completion is once-only");});
  foreach(string changed in new[]{"timeout","clockback","turn","client","player","map","tilepool","data","snapshot","dead","body","owner","unhidden","fog","blackout","clear"})Test("hidden-departure-revocation-"+changed,()=>{
   var r=Setup();var p=CommitAndTake(r,Observe(r))!;Check(p!=null,"initial departure accepted");switch(changed){case "timeout":Now+=3.1;break;case "clockback":Now-=1;break;case "turn":r.State.CurrentTurn++;break;case "client":GameManager.Client=new();break;case "player":GameManager.LocalPlayer=new(){Id=2};break;case "map":MapRenderer.Current=new();break;case "tilepool":r.Map.Tiles[0]=new(){Data=r.Map.Tiles[0].Data};break;case "data":r.Map.Tiles[0].Data=new(){coordinates=new(1,1),unit=r.A.UnitState};break;case "snapshot":var f=NativeGameStateEnvelope.Get(r.State)!;NativeGameStateEnvelope.Bindings[r.State]=new(f.Revision,f.Bytes());break;case "dead":r.A.UnitState.health=0;break;case "body":r.Map.Tiles[0].Data.unit=new(){id=11,coordinates=new(1,1)};break;case "owner":r.A.UnitState.owner=3;break;case "unhidden":r.Map.Tiles[0].Data.Visible=true;break;case "fog":r.Map.Tiles[0].IsHidden=true;break;case "blackout":r.Map.Tiles[0].Data.Explored=false;break;case "clear":NativeExchangeTransformationVisual.ClearDisappearances();break;}
   Check(!NativeExchangeTransformationVisual.CanShowDisappearance(p,1,1),"stale/hidden-source cue permission revoked");
  });
  Test("hidden-departure-prunes-unclaimed-expired-cue",()=>{var r=Setup();var t=Observe(r);t.Commit();t.Complete?.Invoke();Now+=3.1;NativeExchangeTransformationVisual.PruneDisappearances();Check(NativeExchangeTransformationVisual.PendingDisappearances==0,"unclaimed event does not retain objects past bound");});
  Console.WriteLine(JsonSerializer.Serialize(new{passed=true,cases=Cases.Count,assertions=Assertions,tests=Cases,nativeGame="NOT RUN"}));return 0;
 }catch(Exception e){Console.WriteLine(JsonSerializer.Serialize(new{passed=false,error=e.Message,inner=e.InnerException?.Message,cases=Cases.Count,assertions=Assertions}));return 0;}}
